script.setup:
// chroma.js builds the palette: a scale through three colors, interpolated in the chosen color space
// (optionally as a Bézier curve, with lightness evened out), then cut into one class per ridge.
const mod = await ctx.utils.import("https://esm.sh/chroma-js@3.2.0");
const chroma = mod.default ?? mod;
const fs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform float u_time; uniform float u_speed;
uniform int u_layers; uniform vec3 u_cls[12]; uniform vec3 u_ramp[64]; uniform vec3 u_sky; uniform vec3 u_sun;
float h1(float n) { return fract(sin(n) * 43758.5453); }
float vnoise(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(h1(i), h1(i + 1.0), f); }
float ridge(float x, float k) {
  float a = 0.0, amp = 0.5, fr = 1.0;
  for (int o = 0; o < 5; o++) { a += amp * vnoise(x * fr + k * 17.3); fr *= 2.03; amp *= 0.5; }
  return a;
}
vec3 rampAt(float t) { float x = clamp(t, 0.0, 1.0) * 63.0; int i = int(floor(x)); return mix(u_ramp[i], u_ramp[min(i + 1, 63)], fract(x)); }
void main() {
  float aspect = u_resolution.x / u_resolution.y;
  float strip = 0.13;
  if (v_uv.y < strip) {
    // legend: continuous scale on top, the classes below
    float y = v_uv.y / strip;
    vec3 c = y > 0.52 ? rampAt(v_uv.x) : u_cls[min(int(v_uv.x * float(u_layers)), u_layers - 1)];
    float gap = smoothstep(0.46, 0.48, y) * (1.0 - smoothstep(0.52, 0.54, y));
    outColor = vec4(mix(c, vec3(0.06), gap), 1.0); return;
  }
  vec2 p = vec2(v_uv.x * aspect, (v_uv.y - strip) / (1.0 - strip));
  vec3 col = mix(mix(u_sky, vec3(1.0), 0.45), u_sky, smoothstep(0.45, 1.0, p.y));
  vec2 sp = vec2(aspect * 0.72, 0.8);
  float sd = length(p - sp);
  col = mix(col, u_sun, smoothstep(0.105, 0.1, sd));
  col += u_sun * 0.18 * exp(-sd * 6.0);
  float n = float(u_layers);
  for (int i = 0; i < 12; i++) {
    if (i >= u_layers) break;
    float fi = float(i), depth = (fi + 1.0) / n;
    float base = 0.78 - 0.72 * depth;
    float x = p.x * (1.2 + depth * 1.6) + u_time * u_speed * (0.02 + 0.12 * depth * depth);
    float h = base + (0.12 + 0.1 * depth) * ridge(x, fi);
    if (p.y < h) {
      // a little haze at the top edge of each ridge
      float rim = smoothstep(0.03, 0.0, h - p.y);
      col = mix(u_cls[i], mix(u_cls[i], u_sky, 0.25), rim * (1.0 - depth) * 0.6);
    }
  }
  outColor = vec4(col, 1.0);
}`;
Object.assign(ctx.state, { chroma, key: "", cls: new Float32Array(36), ramp: new Float32Array(192), sky: [0, 0, 0], sun: [0, 0, 0],
  MODES: ["rgb", "lab", "lch", "oklch", "bezier"],
  p: ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fs) });

script.render:
const s = ctx.state, u = ctx.uniforms, { chroma } = s;
const hex = (c) => chroma.gl(c[0], c[1], c[2]).hex();
const n = Math.max(3, Math.min(12, u.u_layers | 0));
const key = [u.u_far, u.u_mid, u.u_near, u.u_mode, u.u_correct, n].join("|");
if (key !== s.key) {
  // Rebuild the palette only when a control changed.
  s.key = key;
  const stops = [hex(u.u_far), hex(u.u_mid), hex(u.u_near)];
  const mode = s.MODES[u.u_mode] ?? "lab";
  let scale = mode === "bezier" ? chroma.bezier(stops).scale() : chroma.scale(stops).mode(mode);
  if (u.u_correct) scale = scale.correctLightness();
  for (let i = 0; i < 64; i++) s.ramp.set(scale(i / 63).gl().slice(0, 3), i * 3);
  scale.colors(n, null).forEach((c, i) => s.cls.set(c.gl().slice(0, 3), i * 3));
  s.sky = chroma.mix(stops[0], stops[1], 0.3, "lab").gl().slice(0, 3);
  s.sun = chroma.mix(stops[0], "white", 0.5, "lab").gl().slice(0, 3);
  ctx.publish("classes", scale.colors(n).join(" "));
}
ctx.utils.drawFullscreen(s.p, { u_layers: n, u_cls: s.cls, u_ramp: s.ramp, u_sky: s.sky, u_sun: s.sun });
